CREATE TABLE public.staff_attention (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_key text NOT NULL UNIQUE, person_id uuid NOT NULL REFERENCES public.persons(id), hosting_id uuid REFERENCES public.hostings(id), shabbat_date date NOT NULL, kind text NOT NULL, strong boolean NOT NULL DEFAULT false, due_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN('open','handling','closed')), assigned_to uuid REFERENCES auth.users(id), called_at timestamptz, note text, result text, action_taken text, closed_at timestamptz, overdue boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.staff_attention TO service_role;
ALTER TABLE public.staff_attention ENABLE ROW LEVEL SECURITY;
CREATE TRIGGER staff_attention_updated BEFORE UPDATE ON public.staff_attention FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
INSERT INTO public.app_settings(key,value) VALUES('staff_attention_thresholds','{"late_hours":72,"late_count":2,"late_months":3,"decline_count":3,"unanswered_count":4,"response_months":2,"due_weekday":2}'::jsonb) ON CONFLICT(key) DO NOTHING;
CREATE FUNCTION public.refresh_staff_attention(_actor uuid,_now timestamptz DEFAULT now()) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE demo boolean; ids uuid[]; cfg jsonb; BEGIN
 demo:=public.staff_access(_actor); SELECT array_agg(id) INTO ids FROM public.persons WHERE NOT demo OR id IN('809f85d8-4640-4860-badc-45cba7b5fb4a','ed5895e3-934e-4220-91a1-f70cc937103c'); SELECT value INTO cfg FROM public.app_settings WHERE key='staff_attention_thresholds';
 WITH scoped AS (SELECT h.* FROM public.hostings h WHERE h.guest_id=ANY(ids) AND h.host_id=ANY(ids)), events AS (
 SELECT 'first:'||h.id||':'||p.uid event_key,p.uid person_id,h.id hosting_id,h.shabbat_date,'first' kind,false strong FROM scoped h CROSS JOIN LATERAL (VALUES(h.guest_id),(h.host_id)) p(uid) WHERE h.status IN('confirmed','took_place','did_not_take_place') AND NOT EXISTS(SELECT 1 FROM public.hostings x WHERE p.uid IN(x.guest_id,x.host_id) AND x.status IN('confirmed','took_place','did_not_take_place') AND (x.shabbat_date,x.created_at,x.id)<(h.shabbat_date,h.created_at,h.id))
 UNION ALL SELECT 'alone:'||h.id,h.guest_id,h.id,h.shabbat_date,'alone',false FROM scoped h WHERE h.party_size=1 AND h.status IN('confirmed','took_place','did_not_take_place')
 UNION ALL SELECT 'feedback:'||a.id,a.target_person_id,h.id,h.shabbat_date,CASE WHEN (a.details->>'partial')::boolean THEN 'partial' ELSE 'bad' END,COALESCE((a.details->>'strong')::boolean,false) FROM public.audit_log a JOIN scoped h ON h.id::text=a.target_id WHERE a.action='feedback_attention' AND a.target_person_id=ANY(ids)
 UNION ALL SELECT 'late:'||p.uid||':'||max(h.cancelled_at)::text,p.uid,(array_agg(h.id ORDER BY h.cancelled_at DESC))[1],max(h.shabbat_date),'late',false FROM scoped h CROSS JOIN LATERAL (VALUES(h.cancelled_by)) p(uid) WHERE p.uid=ANY(ids) AND h.cancelled_at>=_now-make_interval(months=>COALESCE((cfg->>'late_months')::int,3)) AND h.cancelled_at<=_now AND h.candle_lighting_at-h.cancelled_at<make_interval(hours=>COALESCE((cfg->>'late_hours')::int,72)) AND h.status IN('cancelled_guest','cancelled_host') GROUP BY p.uid HAVING count(*)>=COALESCE((cfg->>'late_count')::int,2)
 UNION ALL SELECT 'declined:'||r.guest_id||':'||max(r.answered_at)::text,r.guest_id,NULL::uuid,max(a.shabbat_date),'declined',false FROM public.responses r JOIN public.availability a ON a.id=r.availability_id WHERE r.guest_id=ANY(ids) AND r.host_id=ANY(ids) AND r.status='declined' AND r.answered_at BETWEEN _now-make_interval(months=>COALESCE((cfg->>'response_months')::int,2)) AND _now GROUP BY r.guest_id HAVING count(*)>=COALESCE((cfg->>'decline_count')::int,3)
 UNION ALL SELECT 'unanswered:'||r.host_id||':'||max(r.expires_at)::text,r.host_id,NULL::uuid,max(a.shabbat_date),'unanswered',false FROM public.responses r JOIN public.availability a ON a.id=r.availability_id WHERE r.guest_id=ANY(ids) AND r.host_id=ANY(ids) AND r.status='expired' AND r.expires_at BETWEEN _now-make_interval(months=>COALESCE((cfg->>'response_months')::int,2)) AND _now GROUP BY r.host_id HAVING count(*)>=COALESCE((cfg->>'unanswered_count')::int,4))
 INSERT INTO public.staff_attention(event_key,person_id,hosting_id,shabbat_date,kind,strong,due_at) SELECT event_key,person_id,hosting_id,shabbat_date,kind,strong,((shabbat_date+((COALESCE((cfg->>'due_weekday')::int,2)+1)%7+1))::timestamp AT TIME ZONE 'Asia/Jerusalem')-interval '1 microsecond' FROM events ON CONFLICT(event_key) DO NOTHING;
 UPDATE public.staff_attention SET overdue=due_at<_now WHERE person_id=ANY(ids) AND (NOT demo OR hosting_id IS NULL OR hosting_id IN(SELECT id FROM public.hostings WHERE guest_id=ANY(ids) AND host_id=ANY(ids))) AND status<>'closed'; END $$;
CREATE FUNCTION public.staff_operations(_actor uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE demo boolean; ids uuid[]; BEGIN demo:=public.staff_access(_actor); SELECT array_agg(id) INTO ids FROM public.persons WHERE NOT demo OR id IN('809f85d8-4640-4860-badc-45cba7b5fb4a','ed5895e3-934e-4220-91a1-f70cc937103c'); PERFORM public.refresh_staff_attention(_actor);
RETURN jsonb_build_object('hostings',COALESCE((SELECT jsonb_agg(to_jsonb(h)||jsonb_build_object('guest_name',concat_ws(' ',g.first_name,g.last_name),'host_name',hp.family_name,'guest_city',gp.city,'host_city',hp.city,'parsha',s.parsha,'tags',COALESCE((SELECT jsonb_agg(a.kind) FROM public.staff_attention a WHERE a.hosting_id=h.id AND a.status<>'closed'),'[]'::jsonb)) ORDER BY (h.shabbat_date>=(now() AT TIME ZONE 'Asia/Jerusalem')::date) DESC,CASE WHEN h.shabbat_date>=(now() AT TIME ZONE 'Asia/Jerusalem')::date THEN h.shabbat_date END ASC,h.shabbat_date DESC) FROM public.hostings h JOIN public.persons g ON g.id=h.guest_id JOIN public.guest_profiles gp ON gp.person_id=h.guest_id JOIN public.host_profiles hp ON hp.person_id=h.host_id JOIN public.shabbatot s ON s.date=h.shabbat_date WHERE h.guest_id=ANY(ids) AND h.host_id=ANY(ids)),'[]'::jsonb),'attention',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a.shabbat_date,a.created_at) FROM public.staff_attention a WHERE a.person_id=ANY(ids) AND (NOT demo OR a.hosting_id IS NULL OR a.hosting_id IN(SELECT id FROM public.hostings WHERE guest_id=ANY(ids) AND host_id=ANY(ids)))),'[]'::jsonb),'notifications',COALESCE((SELECT jsonb_agg(to_jsonb(n) ORDER BY n.created_at DESC) FROM public.notifications n WHERE n.person_id=ANY(ids) OR (NOT demo AND n.person_id IS NULL)),'[]'::jsonb)); END $$;
CREATE FUNCTION public.staff_hosting_action(_actor uuid,_id uuid,_action text,_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE demo boolean; h public.hostings; BEGIN demo:=public.staff_access(_actor); IF _action NOT IN('cancel','note') OR length(trim(COALESCE(_note,'')))=0 OR length(_note)>2000 THEN RAISE EXCEPTION 'reason_required'; END IF;
 SELECT * INTO h FROM public.hostings WHERE id=_id; IF h.id IS NULL OR (demo AND (h.guest_id<>'809f85d8-4640-4860-badc-45cba7b5fb4a' OR h.host_id<>'ed5895e3-934e-4220-91a1-f70cc937103c')) THEN RAISE EXCEPTION 'Forbidden'; END IF;
 PERFORM 1 FROM public.persons WHERE id=h.guest_id FOR UPDATE; PERFORM 1 FROM public.availability WHERE id=h.availability_id FOR UPDATE; SELECT * INTO h FROM public.hostings WHERE id=_id FOR UPDATE;
 IF _action='cancel' THEN IF h.status<>'confirmed' THEN RAISE EXCEPTION 'hosting_unavailable'; END IF; UPDATE public.hostings SET status='cancelled_staff',cancelled_by=_actor,cancel_reason='staff',cancel_note=trim(_note),cancelled_at=now() WHERE id=h.id; UPDATE public.availability SET seats_left=LEAST(seats,seats_left+h.party_size) WHERE id=h.availability_id; UPDATE public.requests SET status='active' WHERE id=(SELECT request_id FROM public.responses WHERE id=h.response_id); INSERT INTO public.notification_events(person_id,template,entity_id,event_key) VALUES(h.guest_id,'hosting_cancelled',h.id,'staff-cancel:'||h.id||':guest'),(h.host_id,'hosting_cancelled',h.id,'staff-cancel:'||h.id||':host') ON CONFLICT(event_key) DO NOTHING;
 ELSE UPDATE public.hostings SET staff_notes=trim(_note) WHERE id=h.id; END IF;
 INSERT INTO public.audit_log(actor_id,action,target_person_id,target_table,target_id,reason) VALUES(_actor,'staff_hosting_'||_action,h.guest_id,'hostings',h.id::text,trim(_note)); END $$;
CREATE FUNCTION public.staff_attention_action(_actor uuid,_id uuid,_action text,_note text DEFAULT '',_result text DEFAULT NULL,_taken text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE demo boolean; a public.staff_attention; BEGIN demo:=public.staff_access(_actor); SELECT * INTO a FROM public.staff_attention WHERE id=_id FOR UPDATE;
 IF a.id IS NULL OR (demo AND (a.person_id NOT IN('809f85d8-4640-4860-badc-45cba7b5fb4a','ed5895e3-934e-4220-91a1-f70cc937103c') OR (a.hosting_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.hostings WHERE id=a.hosting_id AND guest_id='809f85d8-4640-4860-badc-45cba7b5fb4a' AND host_id='ed5895e3-934e-4220-91a1-f70cc937103c')))) THEN RAISE EXCEPTION 'Forbidden'; END IF;
 IF _action NOT IN('claim','called','note','close') OR length(_note)>2000 OR (_action IN('close','note') AND length(trim(COALESCE(_note,'')))=0) THEN RAISE EXCEPTION 'reason_required'; END IF;
 IF _action='close' AND a.kind='partial' AND (_result IS NULL OR _result NOT IN('misunderstanding','charter','host_problem','other') OR _taken IS NULL OR _taken NOT IN('none','remark','warning','suspension')) THEN RAISE EXCEPTION 'partial_result_required'; END IF;
 UPDATE public.staff_attention SET assigned_to=_actor,status=CASE WHEN _action='close' THEN 'closed' ELSE 'handling' END,called_at=CASE WHEN _action='called' THEN now() ELSE called_at END,note=CASE WHEN length(trim(_note))>0 THEN trim(_note) ELSE note END,result=COALESCE(_result,result),action_taken=COALESCE(_taken,action_taken),closed_at=CASE WHEN _action='close' THEN now() ELSE closed_at END WHERE id=a.id;
 INSERT INTO public.audit_log(actor_id,action,target_person_id,target_table,target_id,reason,details) VALUES(_actor,'attention_'||_action,a.person_id,'staff_attention',a.id::text,NULLIF(trim(_note),''),jsonb_build_object('result',_result,'action',_taken)); END $$;
CREATE FUNCTION public.staff_timed_rules(_actor uuid,_now timestamptz,_simulate boolean DEFAULT false) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE demo boolean; opened integer:=0; BEGIN demo:=public.staff_access(_actor); IF _simulate AND NOT demo THEN RAISE EXCEPTION 'demo_only'; END IF;
 IF _simulate THEN SELECT count(*) INTO opened FROM public.hostings h CROSS JOIN LATERAL (VALUES(h.guest_id),(h.host_id)) p(uid) WHERE h.guest_id='809f85d8-4640-4860-badc-45cba7b5fb4a' AND h.host_id='ed5895e3-934e-4220-91a1-f70cc937103c' AND h.status IN('confirmed','took_place','did_not_take_place') AND h.feedback_opens_at>now() AND h.feedback_opens_at<=_now AND NOT EXISTS(SELECT 1 FROM public.feedback f WHERE f.hosting_id=h.id AND f.author_id=p.uid);
 UPDATE public.hostings SET feedback_opens_at=LEAST(feedback_opens_at,now()) WHERE guest_id='809f85d8-4640-4860-badc-45cba7b5fb4a' AND host_id='ed5895e3-934e-4220-91a1-f70cc937103c' AND status IN('confirmed','took_place','did_not_take_place') AND feedback_opens_at<=_now; END IF;
 PERFORM public.refresh_staff_attention(_actor,_now); RETURN opened; END $$;
REVOKE ALL ON FUNCTION public.refresh_staff_attention(uuid,timestamptz),public.staff_operations(uuid),public.staff_hosting_action(uuid,uuid,text,text),public.staff_attention_action(uuid,uuid,text,text,text,text),public.staff_timed_rules(uuid,timestamptz,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.refresh_staff_attention(uuid,timestamptz),public.staff_operations(uuid),public.staff_hosting_action(uuid,uuid,text,text),public.staff_attention_action(uuid,uuid,text,text,text,text),public.staff_timed_rules(uuid,timestamptz,boolean) TO service_role;